examples.command:
robocopy C:\{{DIR}} D:\{{DIR}} /E /COPYALL
rmdir /s /q C:\{{DIR}}
mklink /J C:\{{DIR}} D:\{{DIR}}

$j = Start-Job -Name scan -ScriptBlock { Get-ChildItem C:\ -Recurse -Filter *.log -ErrorAction SilentlyContinue }
Get-Job
Receive-Job -Name scan -Wait -AutoRemoveJob

systemctl edit {{SERVICE}}
systemctl daemon-reload
systemctl restart {{SERVICE}}

netsh interface ip set address name="{{IFACE}}" static {{IP}} {{NETMASK}} {{GATEWAY}}
netsh interface ip set dns name="{{IFACE}}" static {{DNS1}}
netsh interface ip add dns name="{{IFACE}}" {{DNS2}} index=2

add-apt-repository -y ppa:{{PPA_USER}}/{{PPA_NAME}}
apt update
apt install {{PACKAGE}}

mkfs.xfs {{DEVICE}}
mkdir -p {{MOUNT_POINT}}
echo "UUID=$(blkid -s UUID -o value {{DEVICE}}) {{MOUNT_POINT}} xfs defaults,nofail 0 0" >> /etc/fstab
systemctl daemon-reload
mount -a
df -hT {{MOUNT_POINT}}

lvcreate -n {{LV}} -l 100%FREE {{VG}}
mkfs.xfs /dev/{{VG}}/{{LV}}
mkdir -p {{MOUNT_POINT}}
echo '/dev/mapper/{{VG}}-{{LV}} {{MOUNT_POINT}} xfs defaults 0 0' >> /etc/fstab
systemctl daemon-reload
mount -a

diskpart
list disk
select disk {{DISK_NUMBER}}
online disk
attributes disk clear readonly
convert gpt
create partition primary
format fs=ntfs quick label={{LABEL}}
assign letter={{DRIVE}}
exit

fdisk {{DEVICE}}
# g → n → Enter(기본값) → Enter → Enter → w
partprobe {{DEVICE}}
lsblk {{DEVICE}}

aa-complain /etc/apparmor.d/{{PROFILE}}
# 확인 후 다시 enforce
aa-enforce /etc/apparmor.d/{{PROFILE}}

export http_proxy=http://{{HOST}}:{{PORT}}
export https_proxy=$http_proxy
export no_proxy=localhost,127.0.0.1,.{{DOMAIN}}

if (!(Test-Path $PROFILE)) { New-Item -ItemType File -Path $PROFILE -Force }
Add-Content $PROFILE 'function ll { Get-ChildItem -Force @args }'
. $PROFILE
